// Payload dari ESP2 diasumsikan bentuknya:
// { suhu: 24, kelembapan: 68, soil: 580, rain: 720, pompa: "ON" }

const d = msg.payload || {};

// Hitung status hujan
const rainStatus = d.rain < 700 ? "🌧 Hujan" : "☀ Cerah";

// Ambil state sebelumnya untuk cek perubahan
const prevState = flow.get('moissense_state') || {};

// Simpan state terbaru ke flow context
const state = {
    suhu: d.suhu || 0,
    kelembapan: d.kelembapan || 0,
    soil: d.soil || 0,
    rain_raw: d.rain || 0,
    rain_status: rainStatus,
    pompa: d.pompa || "OFF",
    updated_at: Date.now()
};
flow.set('moissense_state', state);

// Buat event history sederhana (max 50 item)
let events = flow.get('moissense_events') || [];

// Tambah event hanya jika ada perubahan penting (pompa atau hujan)
if (prevState.pompa !== state.pompa) {
    events.unshift({
        ts: new Date().toISOString(),
        type: state.pompa === 'ON' ? 'Pump ON' : 'Pump OFF',
        level: 'info',
        message: `Pump ${state.pompa} (soil=${state.soil})`
    });
}
if (prevState.rain_status !== state.rain_status) {
    events.unshift({
        ts: new Date().toISOString(),
        type: 'Rain',
        level: 'info',
        message: `Cuaca berubah: ${state.rain_status}`
    });
}

// Tambah event warning ketika soil sangat kering (contoh threshold)
if (state.soil < 300 && prevState.soil >= 300) {
    events.unshift({
        ts: new Date().toISOString(),
        type: 'Warning',
        level: 'warn',
        message: `Tanah kering, nilai soil=${state.soil}`
    });
}

// Batasi hanya 50 event terbaru
if (events.length > 50) {
    events = events.slice(0, 50);
}
flow.set('moissense_events', events);

// Output untuk dashboard Node-RED (jika masih ingin dipakai)
const msgSuhu = { payload: state.suhu };
const msgKelembapan = { payload: state.kelembapan };
const msgSoil = { payload: state.soil };
const msgRain = { payload: state.rain_status };
const msgPompa = { payload: state.pompa };

return [msgSuhu, msgKelembapan, msgSoil, msgRain, msgPompa];

const state = flow.get('moissense_state') || {};

// Jika belum ada data, kembalikan default
if (!state.updated_at) {
    msg.payload = {
        suhu: 0,
        kelembapan: 0,
        soil: 0,
        rain_status: "-",
        pompa: "OFF",
        updated_at: null
    };
} else {
    msg.payload = state;
}

return msg;

const events = flow.get('moissense_events') || [];
msg.payload = events;
return msg;

const body = msg.payload || {};
let cmd = (body.cmd || "").toString().toUpperCase();

if (cmd !== 'ON' && cmd !== 'OFF') {
    msg.statusCode = 400;
    msg.payload = { error: "cmd must be 'ON' or 'OFF'" };
    return [null, msg];
}

// Update state di flow
let state = flow.get('moissense_state') || {};
state.pompa = cmd;
state.updated_at = Date.now();
flow.set('moissense_state', state);

// Tambah event
let events = flow.get('moissense_events') || [];
events.unshift({
    ts: new Date().toISOString(),
    type: cmd === 'ON' ? 'Pump ON' : 'Pump OFF',
    level: 'info',
    message: `Pump ${cmd} via API`
});
if (events.length > 50) events = events.slice(0, 50);
flow.set('moissense_events', events);

// Output 1 → MQTT OUT, Output 2 → HTTP Response
const msgMqtt = {
    topic: 'smartfarm/pompa',
    payload: cmd
};

const msgHttp = {
    payload: { status: 'ok', pump_state: cmd }
};

return [msgMqtt, msgHttp];
